(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*18+Math.sin(x*0.016+t*0.33)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8+Math.cos(sy*0.02+t*0.5)*6;
  const w2y = Math.cos(sy*0.022+t*0.45)*8+Math.sin(sx*0.018-t*0.35)*6;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*55, 0.11, 2.1, 0.9],
    [400+Math.cos(t*0.55+1)*60, 210+Math.sin(t*0.75+4)*50, 0.065, 2.4, 1.0],
    [200+Math.sin(t*0.42+6)*110, 30+Math.cos(t*0.62+3)*70, 0.085, 1.8, 1.1],
    [300+Math.cos(t*0.38+2)*95, 100+Math.sin(t*0.58+5)*65, 0.075, 2.2, 0.88]
  ];
  let aS=0, iS=0, fS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    const wave2=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const wave3=Math.sin(d*f*1.3-t*sp*0.4+3.0);
    aS+=wave*w; iS+=wave2*w; fS+=wave3*w;
  }
  const n=10, act=aS/n, inh=iS/n, feed=fS/n;
  const bg=(Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    +Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const vortex=Math.sin(dist*0.03-ang*6-t*2.0)*Math.exp(-dist*0.003)*0.5;
  const laplacian=(Math.sin(dx*0.2)*Math.sin(dy*0.2)+Math.sin(dx*0.15-dy*0.15+t*0.7))*0.3;
  const reaction1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const reaction2=Math.tanh((feed*0.5+inh*0.4-act*0.3+vortex+laplacian)*1.8);
  const cross=Math.tanh((reaction1*reaction2+spiral*0.5+vortex)*2.0);
  const cell=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(dx*0.3+t*1.5)*Math.sin(dy*0.3-t*1.2)*0.15;
  const blend=cross*0.45+reaction1*0.2+reaction2*0.1+cell*0.15+micro*0.1;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,48],[12,35,85],[18,65,120],[15,100,130],[25,140,135],
    [80,165,115],[170,175,70],[210,165,55],[220,125,65],[195,75,60],
    [155,45,70],[100,25,75],[55,15,60],[25,10,50],[5,12,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const energy=Math.abs(reaction1)+Math.abs(reaction2);
  const lum=0.75+energy*0.15+Math.sin(cross*Math.PI)*0.1;
  const edge=Math.abs(cross)>0.6?1.2:Math.abs(reaction1)>0.7?1.1:1.0;
  const glow=Math.exp(-energy*0.5)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*90))|0
  ];
}
